static void require_date(sqlite3 *db, const char *flag, const char *value);
static void index_prepare(sqlite3 *db);

typedef struct {
  int all, limit, nwords, history, json;
  const char *as_of, *since;
  char **words; /* positional search words; caller frees */
} search_opts;

static void search_options(search_opts *o, int argc, char **argv) {
  *o = (search_opts){.limit = 12};
  o->words = calloc((size_t)argc + 1, sizeof *o->words);
  if (!o->words) die("out of memory");
  for (int i = 0; i < argc; i++) {
    if (!strcmp(argv[i], "--all")) o->all = 1;
    else if (!strcmp(argv[i], "--history")) o->history = 1;
    else if (!strcmp(argv[i], "--as-of") && i + 1 < argc) o->as_of = argv[++i];
    else if (!strcmp(argv[i], "--since") && i + 1 < argc) o->since = argv[++i];
    else if (!strcmp(argv[i], "--json")) o->json = 1;
    else if (!strcmp(argv[i], "--limit") && i + 1 < argc) o->limit = (int)parse_count("--limit", argv[++i]);
    else if (!strncmp(argv[i], "--", 2)) die("unknown option %s", argv[i]);
    else o->words[o->nwords++] = argv[i];
  }
}

static int cmd_search(int argc, char **argv) {
  search_opts o;
  search_options(&o, argc, argv);
  int all = o.all, limit = o.limit, nwords = o.nwords, history = o.history, json = o.json;
  const char *as_of = o.as_of, *since = o.since;
  char **words = o.words;
  buf q = {0};
  if (!fts_query(nwords, words, &q)) die("no search words");
  free(words);
  sqlite3 *db = ctx_open();
  if (as_of) {
    require_date(db, "--as-of", as_of);
    index_prepare(db);
  }
  if (since) require_date(db, "--since", since);
  char *project = all ? NULL : current_project(db);
  int hits = search_run(db, q.p, project, limit, history, as_of, since, json);
  if (!hits && project) {
    fprintf(stderr, "ctx: nothing in project %s; searching everything\n", project);
    hits = search_run(db, q.p, NULL, limit, history, as_of, since, json);
  }
  if (!hits) fprintf(stderr, "ctx: no matches\n");
  free(project);
  free(q.p);
  sqlite3_close(db);
  return 0;
